cd /c/Users/Fatal/Desktop/specs_hackathon/pallet_lens; python -c "
import json
for f in ['devpost/agent-logs/02-build.jsonl','devpost/agent-logs/03-build-continue.jsonl']:
  lines=[l for l in open(f,encoding='utf-8').read().splitlines() if l.strip()]
  print('=====',f,len(lines))
  for l in reversed(lines):
    try: d=json.loads(l)
    except: continue
    if d.get('type')=='result': print(d.get('result')); break
"; cat devpost/agent-logs/03-build-continue.err | tail -20

