  private wantVisible = true
  private currentText = ""
  private camT: Transform | null = null

  onAwake(): void {
    this.wantVisible = this.startVisible
    this.currentText = this.initialText
    this.sceneObject.createComponent("Component.Canvas")
    this.backPlate = this.sceneObject.createComponent(BackPlate.getTypeName()) as BackPlate
    this.backPlate.size = new vec2(this.panelWidth, this.panelHeight)

    const content = global.scene.createSceneObject("Content")
    content.setParent(this.sceneObject)
    content.getTransform().setLocalPosition(new vec3(0, 0, 0.6))
    this.text = content.createComponent("Component.Text") as Text
    this.text.depthTest = true
    this.text.size = this.textSize
    this.text.textFill.color = this.textColor
    this.text.horizontalAlignment = HorizontalAlignment.Center
    this.text.verticalAlignment = VerticalAlignment.Center
    this.text.horizontalOverflow = HorizontalOverflow.Shrink
    this.text.verticalOverflow = VerticalOverflow.Shrink
    const hw = this.panelWidth / 2 - 0.8
    const hh = this.panelHeight / 2 - 0.5
    this.text.layoutRect = Rect.create(-hw, hw, -hh, hh)
    this.text.text = this.currentText

    this.backPlate.onInitialized.add(() => {
      this.backPlate.size = new vec2(this.panelWidth, this.panelHeight)
      this.ready = true
      this.sceneObject.enabled = this.wantVisible
    })

    this.createEvent("UpdateEvent").bind(() => this.faceUser())
  }

  setText(msg: string): void {
    this.currentText = msg
    if (this.text) this.text.text = msg
  }

  getText(): string {
    return this.currentText
  }

  setTextColor(c: vec4): void {
    if (this.text) this.text.textFill.color = c
  }

  setVisible(v: boolean): void {
    this.wantVisible = v
    if (this.ready) this.sceneObject.enabled = v
  }

  /** Logical visibility (what the controller asked for). */
  isVisible(): boolean {
    return this.wantVisible
  }

  private faceUser(): void {
    if (!this.faceCamera) return
    if (!this.camT) {
      const cam = WorldCameraFinderProvider.getInstance()
      if (!cam) return
      this.camT = cam.getTransform()
    }
    const t = this.sceneObject.getTransform()
    const dir = this.camT.getWorldPosition().sub(t.getWorldPosition())
    if (dir.length < 0.001) return
    t.setWorldRotation(quat.lookAt(dir.normalize(), vec3.up()))
  }
}
// StackRightResetButtonUI.ts
// Owns: the "Reset pallet" pinch button (UIKit Button + raw label), which sits on a short post
// at the pallet's near corner. Emits onReset; the controller decides what Reset does.
// Expects: nothing wired. Must not: change game state itself.
import {Button} from "SpectaclesUIKit.lspkg/Scripts/Components/Button/Button"
import Event, {PublicApi} from "SpectaclesInteractionKit.lspkg/Utils/Event"
import WorldCameraFinderProvider from "SpectaclesInteractionKit.lspkg/Providers/CameraProvider/WorldCameraFinderProvider"

const BUTTON_LABEL_Z = 0.08

@component
export class StackRightResetButtonUI extends BaseScriptComponent {
  @ui.label('<span style="color: #60A5FA;">StackRightResetButtonUI – big pinch button that resets the pallet</span>')
  @ui.separator

  @ui.label('<span style="color: #60A5FA;">Settings</span>')
  @ui.group_start("Settings")
  @input
  @hint("Button label")
  label: string = "Reset pallet"

  @input
  @hint("Button width in cm (brief: about 12 cm)")
  @widget(new SliderWidget(6, 30, 0.5))
  buttonWidth: number = 12

  @input
  @hint("Button height in cm")
  @widget(new SliderWidget(3, 15, 0.5))
  buttonHeight: number = 6

  @input
  @hint("Label text size")
  @widget(new SliderWidget(30, 120, 1))
  labelSize: number = 56

  @input
  @hint("Turn the button every frame so it faces the user")
  faceCamera: boolean = true
  @ui.group_end

  private _onReset = new Event<void>()
  get onReset(): PublicApi<void> {
    return this._onReset.publicApi()
  }

  private button: Button
  private camT: Transform | null = null

  onAwake(): void {
    this.sceneObject.createComponent("Component.Canvas")
    const face = global.scene.createSceneObject("ButtonFace")
    face.setParent(this.sceneObject)
    this.button = face.createComponent(Button.getTypeName()) as Button
    this.button.size = new vec3(this.buttonWidth, this.buttonHeight, 1)
    this.button.onInitialized.add(() => {
      this.button.size = new vec3(this.buttonWidth, this.buttonHeight, 1)
    })
    this.button.onTriggerUp.add(() => this._onReset.invoke())

    const labelSO = global.scene.createSceneObject("ButtonLabel")
    labelSO.setParent(face)
    labelSO.getTransform().setLocalPosition(new vec3(0, 0, BUTTON_LABEL_Z + 0.5))
    const t = labelSO.createComponent("Component.Text") as Text
    t.text = this.label
    t.depthTest = true
    t.size = this.labelSize
    t.textFill.color = new vec4(1, 1, 1, 1)
    t.horizontalAlignment = HorizontalAlignment.Center
    t.verticalAlignment = VerticalAlignment.Center
    t.horizontalOverflow = HorizontalOverflow.Shrink
    t.verticalOverflow = VerticalOverflow.Overflow
    const w = this.buttonWidth - 0.5
    t.layoutRect = Rect.create(-w / 2, w / 2, -1.5, 1.5)

    this.createEvent("UpdateEvent").bind(() => this.faceUser())
  }

  /** Same path as a real pinch on the button (used by tests). */
  press(): void {
    this._onReset.invoke()
  }

  private faceUser(): void {
    if (!this.faceCamera) return
    if (!this.camT) {
      const cam = WorldCameraFinderProvider.getInstance()
      if (!cam) return
      this.camT = cam.getTransform()
    }
    const t = this.sceneObject.getTransform()
    const d = this.camT.getWorldPosition().sub(t.getWorldPosition())
    if (d.length < 0.001) return
    t.setWorldRotation(quat.lookAt(d.normalize(), vec3.up()))
  }
}
// StackRightCartonLabelUI.ts
// Owns: the printed labels on one carton (name + "14 kg · HEAVY" / "FRAGILE") on the faces the
// user sees: the side facing the pallet (-X, seen while the carton is on the shelf), the near
// side (+Z, seen on the pallet) and the top. Created at runtime by the controller on each carton.
// Must not: hold game state.

@component
export class StackRightCartonLabelUI extends BaseScriptComponent {
  @ui.label('<span style="color: #60A5FA;">StackRightCartonLabelUI – printed carton labels</span>')
  @ui.separator

  @ui.label('<span style="color: #60A5FA;">Settings</span>')
  @ui.group_start("Settings")
  @input
  @hint("Label text size (about 44 = 1 cm em height)")
  @widget(new SliderWidget(40, 300, 1))
  labelSize: number = 120

  @ui.group_end

  setup(name: string, detail: string, size: vec3): void {
    const hx = size.x / 2, hy = size.y / 2, hz = size.z / 2
    const off = 0.3
    // -X face (seen from the pallet side while on the shelf): +Z normal rotated to -X
    this.face("LabelSide", name, detail, new vec3(-hx - off, 0, 0), quat.angleAxis(-Math.PI / 2, vec3.up()), size.z, size.y)
    // +Z face (near side on the pallet)
    this.face("LabelFront", name, detail, new vec3(0, 0, hz + off), quat.quatIdentity(), size.x, size.y)
    // top face, readable from the user's side
    this.face("LabelTop", name, detail, new vec3(0, hy + off, 0), quat.angleAxis(-Math.PI / 2, vec3.right()), size.x, size.z)
  }

  private face(objName: string, name: string, detail: string, pos: vec3, rot: quat, w: number, h: number): void {
    const so = global.scene.createSceneObject(objName)
    so.setParent(this.sceneObject)
    so.getTransform().setLocalPosition(pos)
    so.getTransform().setLocalRotation(rot)
    const t = so.createComponent("Component.Text") as Text
    t.text = name + "\n" + detail
    t.size = this.labelSize
    t.depthTest = true
    t.textFill.color = new vec4(1, 1, 1, 1)
    t.horizontalAlignment = HorizontalAlignment.Center
    t.verticalAlignment = VerticalAlignment.Center
    t.horizontalOverflow = HorizontalOverflow.Shrink
    t.verticalOverflow = VerticalOverflow.Shrink
    const hw = w / 2 - 2
    const hh = h / 2 - 2
    t.layoutRect = Rect.create(-hw, hw, -hh, hh)
  }
}
// StackRightGeometry.ts
// Owns: tiny helpers that build primitive box visuals (pallet, shelves, cartons, ghost, arrow)
// from one 1 cm box mesh + one unlit material that is cloned per box. These are the obvious
// placeholder visuals; swap the boxMesh / baseMaterial @inputs on the controller to upgrade.
// Scale always lives on the leaf "Visual" child, never on a node that owns a collider.
// Must not: hold game state or create text.

export class BoxFactory {
  constructor(private mesh: RenderMesh, private baseMaterial: Material) {}

  makeMaterial(color: vec4, translucent: boolean): Material {
    const mat = this.baseMaterial.clone()
    mat.mainPass.baseColor = color
    if (translucent) {
      mat.mainPass.blendMode = BlendMode.Normal
      mat.mainPass.depthWrite = false
    }
    return mat
  }

  /** Creates a child SceneObject with a box visual of `size` cm centred at `localPos`. */
  makeBox(parent: SceneObject, name: string, size: vec3, localPos: vec3, color: vec4,
    translucent: boolean = false): RenderMeshVisual {
    const so = global.scene.createSceneObject(name)
    so.setParent(parent)
    const t = so.getTransform()
    t.setLocalPosition(localPos)
    t.setLocalScale(size)
    const rmv = so.createComponent("Component.RenderMeshVisual") as RenderMeshVisual
    rmv.mesh = this.mesh
    rmv.mainMaterial = this.makeMaterial(color, translucent)
    return rmv
  }

  /** 12 thin bars outlining a box of `size` centred at the parent's origin. */
  makeWireBox(parent: SceneObject, name: string, size: vec3, thickness: number, color: vec4): SceneObject {
    const root = global.scene.createSceneObject(name)
    root.setParent(parent)
    const mat = this.makeMaterial(color, true)
    for (let i = 0; i < 12; i++) {
      const bar = global.scene.createSceneObject("Edge" + i)
      bar.setParent(root)
      const rmv = bar.createComponent("Component.RenderMeshVisual") as RenderMeshVisual
      rmv.mesh = this.mesh
      rmv.mainMaterial = mat
    }
    BoxFactory.layoutWireBox(root, size, thickness)
    return root
  }

  static layoutWireBox(root: SceneObject, size: vec3, th: number): void {
    const hx = size.x / 2, hy = size.y / 2, hz = size.z / 2
    const specs: [vec3, vec3][] = []
    for (const sy of [-1, 1]) for (const sz of [-1, 1]) specs.push([new vec3(0, sy * hy, sz * hz), new vec3(size.x + th, th, th)])
    for (const sx of [-1, 1]) for (const sz of [-1, 1]) specs.push([new vec3(sx * hx, 0, sz * hz), new vec3(th, size.y + th, th)])
    for (const sx of [-1, 1]) for (const sy of [-1, 1]) specs.push([new vec3(sx * hx, sy * hy, 0), new vec3(th, th, size.z + th)])
    for (let i = 0; i < 12 && i < root.getChildrenCount(); i++) {
      const t = root.getChild(i).getTransform()
      t.setLocalPosition(specs[i][0])
      t.setLocalScale(specs[i][1])
    }
  }
}
