declare module "LensStudio:TypeScript" {
    /**
    * Plugin component interface for invoking TypeScript compilation on the current project or an isolated tsconfig.


    * @example
    * ```ts
    *     const FileSystem = await import('LensStudio:FileSystem');
    *     const { ITypeScriptCompilationApi } = await import('LensStudio:TypeScript');

    *     const compiler = this.pluginSystem.findInterface(ITypeScriptCompilationApi) as ITypeScriptCompilationApi;
    *     if (Editor.isNull(compiler)) {
    *       console.log('Compilation API not available');
    *       return;
    *     }

    *     const projectResult = await compiler.refreshProjectCompilation();
    *     console.log(`Project compile: succeeded=${projectResult.succeeded} errors=${projectResult.errors.length}`);

    *     const tmp = FileSystem.TempDir.create();
    *     FileSystem.writeFile(
    *       tmp.path.appended(new Editor.Path('a.ts')),
    *       'const x: number = 1; export {};',
    *     );
    *     FileSystem.writeFile(
    *       tmp.path.appended(new Editor.Path('tsconfig.json')),
    *       JSON.stringify({
    *         compilerOptions: { module: 'esnext', target: 'es2021', isolatedModules: true, outDir: 'out' },
    *         include: ['a.ts'],
    *       }),
    *     );
    *     const isolated = await compiler.runIsolatedCompilation(
    *       tmp.path.appended(new Editor.Path('tsconfig.json')).toString(),
    *     );
    *     console.log(`Isolated compile: succeeded=${isolated.succeeded} errors=${isolated.errors.length}`);
    * ```

    */
    class ITypeScriptCompilationApi extends Editor.IPluginComponent {

        /** @hidden */
        protected constructor()

        /**
        * Recompiles the current project TypeScript and resolves with the resulting compilation result.

        */
        refreshProjectCompilation(): Promise<TypeScriptCompilationResult>

        /**
        * Compiles the project at the given tsconfig path in isolation and resolves with the resulting compilation result.

        */
        runIsolatedCompilation(tsconfigPath: string): Promise<TypeScriptCompilationResult>

        /**
        * Returns the type name of this class.
        */
        static getTypeName(): string

        /**
        * Interface identifier for resolving the TypeScript compilation API via the plugin system.

        */
        static interfaceId: Editor.InterfaceId

    }

}

declare module "LensStudio:TypeScript" {
    /**
    * Result of a TypeScript compilation run, containing success status and any reported errors.


    * @example
    * ```ts
    *     const { ITypeScriptCompilationApi } = await import('LensStudio:TypeScript');
    *     const compiler = this.pluginSystem.findInterface(ITypeScriptCompilationApi) as ITypeScriptCompilationApi;
    *     if (Editor.isNull(compiler)) {
    *       console.log('Compilation API not available');
    *       return;
    *     }

    *     const result = await compiler.refreshProjectCompilation();
    *     if (result.succeeded) {
    *       console.log('Compilation succeeded');
    *     } else {
    *       console.log(`Compilation failed with ${result.errors.length} error(s); first: ${result.errors[0] ?? ''}`);
    *     }
    * ```

    */
    class TypeScriptCompilationResult {

        /** @hidden */
        protected constructor()

        /**
        * Array of error messages produced by the compilation.


        * @readonly
        */
        errors: string[]

        /**
        * Whether the compilation completed without errors.


        * @readonly
        */
        succeeded: boolean

    }

}

