// StackRightPickList.ts
// STAND-IN FOR BARCODE SCAN. A real picker's Lens would read the carton's barcode when it is
// picked up. For the preview, the pick list is fixed: 8 cartons in a set order, heaviest first.
// The learner should replace these lines with real lines from their warehouse.
//
// Owns: carton data (name, weight, class, real size in cm, colour) and the slot plan
// (where each carton goes on the 116.5 x 116.5 cm pallet). Pure data, no scene access.
// Must not: touch the scene, hold game state.
//
// Sizes are W (x) x H (y) x D (z) in cm. Slot positions are in Pallet-local cm:
// x right, z toward the user (near edge = +z), y = bottom of the carton above the floor.
// Pallet deck top is at y = 15. Layer 1 cartons are 32 cm tall, so layer 2 sits at y = 47.

export interface CartonSpec {
  key: string // used in scene object names, e.g. Carton_0_Water
  name: string // shown on the carton
  tipName: string // used in the red tip, e.g. "Chips go on top."
  tipVerb: string // "go" / "goes"
  kg: number
  heavy: boolean // false = light + fragile (crushable)
  layer: number // 1 or 2
  size: vec3 // W x H x D, cm
  color: vec4 // bright, light-saturated label colour (additive display: no dark colours)
  slot: vec3 // Pallet-local: x, bottom y, z
}

export const PALLET_SIZE_CM = new vec3(116.5, 15, 116.5)
export const PALLET_DECK_Y = 15

export const PICK_LIST: CartonSpec[] = [
  {key: "Water", name: "WATER 24", tipName: "Water", tipVerb: "goes", kg: 14, heavy: true, layer: 1,
    size: new vec3(56, 32, 46), color: new vec4(0.3, 0.72, 1.0, 1), slot: new vec3(-28.5, 15, -34)},
  {key: "SoftDrink", name: "SOFT DRINK", tipName: "Soft drink", tipVerb: "goes", kg: 9, heavy: true, layer: 1,
    size: new vec3(56, 32, 46), color: new vec4(1.0, 0.45, 0.3, 1), slot: new vec3(28.5, 15, -34)},
  {key: "Tomatoes", name: "TOMATOES", tipName: "Tomatoes", tipVerb: "go", kg: 10, heavy: true, layer: 1,
    size: new vec3(37, 32, 56), color: new vec4(1.0, 0.35, 0.45, 1), slot: new vec3(-38.5, 15, 18)},
  {key: "Laundry", name: "LAUNDRY", tipName: "Laundry", tipVerb: "goes", kg: 17, heavy: true, layer: 1,
    size: new vec3(37, 32, 56), color: new vec4(0.55, 0.5, 1.0, 1), slot: new vec3(0, 15, 18)},
  {key: "Pasta", name: "PASTA", tipName: "Pasta", tipVerb: "goes", kg: 10, heavy: true, layer: 1,
    size: new vec3(37, 32, 56), color: new vec4(1.0, 0.75, 0.2, 1), slot: new vec3(38.5, 15, 18)},
  {key: "Bread", name: "BREAD", tipName: "Bread", tipVerb: "goes", kg: 4, heavy: false, layer: 2,
    size: new vec3(50, 26, 36), color: new vec4(1.0, 0.82, 0.55, 1), slot: new vec3(-29, 47, -33)},
  {key: "Eggs", name: "EGGS", tipName: "Eggs", tipVerb: "go", kg: 10, heavy: false, layer: 2,
    size: new vec3(46, 28, 36), color: new vec4(0.95, 0.9, 0.7, 1), slot: new vec3(27, 47, -33)},
  {key: "Chips", name: "CHIPS", tipName: "Chips", tipVerb: "go", kg: 2, heavy: false, layer: 2,
    size: new vec3(50, 34, 40), color: new vec4(0.45, 1.0, 0.55, 1), slot: new vec3(0, 47, 20)},
]

export function ghostTagText(c: CartonSpec): string {
  return "Layer " + c.layer + " · " + (c.heavy ? "Heavy" : "Light") + " · " + c.kg + " kg"
}
// Shared helpers for the Stack Right LEAF scenarios. Lives in Assets/Tests/.
import {findSceneObjectByName, sleep} from "Leaf.lspkg/Utils/common/Utils"
import {StackRightController} from "../Scripts/StackRightController"

export function getController(): StackRightController {
  const so = findSceneObjectByName("StackRightController")
  if (!so) throw new Error("StackRightController scene object not found")
  const c = so.getComponent(StackRightController.getTypeName()) as StackRightController
  if (!c) throw new Error("StackRightController component not found")
  return c
}

/** Drops carton i a few cm above its slot (inside the 15 cm snap radius). */
export function dropOnSlot(c: StackRightController, i: number): void {
  c.simulateGrab(i)
  c.simulateRelease(i, c.getSlotWorldPosition(i).add(new vec3(0, 5, 0)))
}

/** Waits until every returning carton has slid back to the shelf. */
export async function settle(c: StackRightController): Promise<void> {
  for (let k = 0; k < 40; k++) {
    let busy = false
    for (let i = 0; i < c.getCartonCount(); i++) if (c.isCartonReturning(i)) busy = true
    if (!busy) return
    await sleep(100)
  }
}

export async function freshPallet(c: StackRightController): Promise<void> {
  c.reset()
  await sleep(300)
}

/** The Reset button's UIKit Button lives on a runtime child "ButtonFace" under "ResetButton". */
export function resetButtonFaceName(): string {
  return "ButtonFace"
}
// DC1: at start the pallet is on the floor about 1 m ahead at real size, and the shelf bay
// with 8 cartons is about 1.4 m to the right.
import {Scenario} from "Leaf.lspkg/Scenarios/scenario/Scenario"
import {expect} from "Leaf.lspkg/Utils/common/Expect"
import {findSceneObjectByName, sleep} from "Leaf.lspkg/Utils/common/Utils"
import {getController, freshPallet} from "./StackRightLeafHelpers"

@component
export class StackRightDC1LayoutScenario extends Scenario {
  async run(): Promise<void> {
    await sleep(1500)
    const c = getController()
    await freshPallet(c)
    const cam = c.getCameraWorldPosition()
    const pallet = c.getPalletWorldPosition()
    const shelf = c.getShelfWorldPosition()

    // Pallet: ~100 cm ahead (-z), roughly centred, on the floor (140-170 cm below the eyes).
    const ahead = cam.z - pallet.z
    expect(ahead >= 80 && ahead <= 120).toBe(true)
    expect(Math.abs(pallet.x - cam.x) < 20).toBe(true)
    const drop = cam.y - pallet.y
    expect(drop >= 140 && drop <= 170).toBe(true)

    // Shelf bay: ~140 cm to the right (+x).
    const right = shelf.x - cam.x
    expect(right >= 120 && right <= 160).toBe(true)

    // 8 cartons on the shelf, none placed, all inside the shelf bay's footprint (60 D x 240 W).
    expect(c.getCartonCount()).toBe(8)
    for (let i = 0; i < 8; i++) {
      expect(c.isCartonPlaced(i)).toBe(false)
      const p = c.getCartonWorldPosition(i)
      expect(Math.abs(p.x - shelf.x) <= 30).toBe(true)
      expect(Math.abs(p.z - shelf.z) <= 120).toBe(true)
      expect(p.y > shelf.y + 35).toBe(true)
    }

    // Named scene objects exist; the stand-in pick list is obvious in the hierarchy.
    expect(findSceneObjectByName("Pallet") != null).toBe(true)
    expect(findSceneObjectByName("ShelfBay") != null).toBe(true)
    expect(findSceneObjectByName("PickList (stand-in for barcode scan)") != null).toBe(true)
    expect(c.getCounterText()).toBe("0 / 8")
  }
}

